#include <string>
#include <vector>

class Solution {
public:
    int nextBeautifulNumber(int n) {
        auto isBalanced = [](int x) -> bool {
            int count[10] = {0};
            int temp = x;
            while (temp > 0) {
                count[temp % 10]++;
                temp /= 10;
            }
            for (int d = 0; d < 10; ++d) {
                if (count[d] > 0 && count[d] != d) return false;
            }
            return true;
        };

        int curr = n + 1;
        while (!isBalanced(curr)) {
            curr++;
        }
        return curr;
    }
};

class Solution {
    public int nextBeautifulNumber(int n) {
        int curr = n + 1;
        while (!isBalanced(curr)) {
            curr++;
        }
        return curr;
    }

    private boolean isBalanced(int x) {
        int[] count = new int[10];
        int temp = x;
        while (temp > 0) {
            count[temp % 10]++;
            temp /= 10;
        }
        for (int d = 0; d < 10; d++) {
            if (count[d] > 0 && count[d] != d) return false;
        }
        return true;
    }
}

