var nextBeautifulNumber = function(n) {
    const isBalanced = (x) => {
        const count = new Array(10).fill(0);
        let temp = x;
        while (temp > 0) {
            count[temp % 10]++;
            temp = Math.floor(temp / 10);
        }
        for (let d = 0; d < 10; d++) {
            if (count[d] > 0 && count[d] !== d) return false;
        }
        return true;
    };

    let curr = n + 1;
    while (!isBalanced(curr)) {
        curr++;
    }
    return curr;
};
